test('vatSummary returns empty array for no invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary returns empty array for draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  // Keep as draft

  const result = vatSummary([r.value]);
  assert.deepEqual(result, []);
});

test('vatSummary returns empty array for paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 114950, date: '2024-01-20' });
  assert.equal(paid.ok, true);

  // Paid invoices are included
  const result = vatSummary([paid.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary groups by VAT rate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21); // DEV-HOUR has 21% VAT
  assert.equal(result[0].base, 95000); // 10 * 9500
  assert.equal(result[0].vat, 19950); // 95000 * 0.21
});

test('vatSummary calculates base correctly with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // base = lineTotal - lineDiscount = 95000 - 9500 = 85500
  assert.equal(result[0].base, 85500);
  // vat = 85500 * 0.21 = 17955
  assert.equal(result[0].vat, 17955);
});

test('vatSummary handles multiple VAT rates', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }], // 21% VAT
  });

  assert.equal(r1.ok, true);
  const issued1 = issueInvoice(r1.value, []);
  assert.equal(issued1.ok, true);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'BOOK', qty: 5, discountPercent: 0 }], // 9% VAT
  });

  assert.equal(r2.ok, true);
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']);
  assert.equal(issued2.ok, true);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary sorts by rate descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'BOOK', qty: 5, discountPercent: 0 }], // 9% VAT
  });

  assert.equal(r1.ok, true);
  const issued1 = issueInvoice(r1.value, []);
  assert.equal(issued1.ok, true);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }], // 21% VAT
  });

  assert.equal(r2.ok, true);
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']);
  assert.equal(issued2.ok, true);

  // Add in reverse order to verify sorting
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary accumulates base and vat for same rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }], // 21% VAT
  });

  assert.equal(r1.ok, true);
  const issued1 = issueInvoice(r1.value, []);
  assert.equal(issued1.ok, true);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }], // 21% VAT
  });

  assert.equal(r2.ok, true);
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']);
  assert.equal(issued2.ok, true);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // base = 95000 + 47500 = 142500
  assert.equal(result[0].base, 142500);
  // vat = 19950 + 9975 = 29925
  assert.equal(result[0].vat, 29925);
});

