test('overdueInvoices sorts by daysOverdue descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);

  const issued1 = issueInvoice(r1.value, []);
  assert.equal(issued1.ok, true);
  // Due date: 2024-01-31

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r2.ok, true);

  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']);
  assert.equal(issued2.ok, true);
  // Due date: 2024-02-19

  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r3.ok, true);

  const issued3 = issueInvoice(r3.value, ['INV-2024-0001', 'INV-2024-0002']);
  assert.equal(issued3.ok, true);
  // Due date: 2024-02-09

  // Report date is 2024-03-01
  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2024-03-01');
  assert.equal(result.length, 3);
